def _skip_ows(s, i, n):
    while i < n and (s[i] == " " or s[i] == "\t"):
        i += 1
    return i


def _skip_quoted(s, i, n):
    # s[i] == '"' ; returns index just after the closing quote
    i += 1
    while i < n:
        c = s[i]
        if c == "\\":
            if i + 1 >= n:
                raise Reject("fields")
            d = s[i + 1]
            if d == "\t" or ("\x21" <= d <= "\x7e"):
                i += 2
                continue
            raise Reject("fields")
        if c == '"':
            return i + 1
        if c == " " or c == "\t" or ("\x21" <= c <= "\x7e"):
            i += 1
            continue
        raise Reject("fields")
    raise Reject("fields")


def _parse_bracket(s, i, n):
    j = s.find(">", i + 1)
    if j < 0:
        raise Reject("fields")
    uri, is_tel = canon_uri(s[i + 1:j])
    if uri is None:
        raise Reject("fields")
    return uri, is_tel, j + 1


def parse_address(s, i, n):
    """Parse one address starting at index i. Returns (uri, is_tel, next)."""
    i = _skip_ows(s, i, n)
    if i >= n:
        raise Reject("fields")
    c = s[i]
    if c == "<":
        return _parse_bracket(s, i, n)
    if c == '"':
        j = _skip_quoted(s, i, n)
        j = _skip_ows(s, j, n)
        if j >= n or s[j] != "<":
            raise Reject("fields")
        return _parse_bracket(s, j, n)
    k = s.find("<", i)
    if k >= 0:
        dn = s[i:k].rstrip(_OWS)
        if not dn or not DN_RE.fullmatch(dn):
            raise Reject("fields")
        return _parse_bracket(s, k, n)
    m = i
    while m < n and s[m] not in _STOP:
        m += 1
    uri, is_tel = canon_uri(s[i:m])
    if uri is None:
        raise Reject("fields")
    return uri, is_tel, m


def _split_commas(s):
    out = []
    cur = []
    depth = 0
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"' and depth == 0:
            j = _skip_quoted(s, i, n)
            cur.append(s[i:j])
            i = j
            continue
        if c == "<":
            depth += 1
            cur.append(c)
            i += 1
            continue
        if c == ">":
            if depth > 0:
                depth -= 1
            cur.append(c)
            i += 1
            continue
        if c == "," and depth == 0:
            out.append("".join(cur))
            cur = []
            i += 1
            continue
        cur.append(c)
        i += 1
    out.append("".join(cur))
    return out


def parse_from(v):
    n = len(v)
    uri, is_tel, j = parse_address(v, 0, n)
    j = _skip_ows(v, j, n)
    if j >= n or v[j] != ";":
        raise Reject("fields")
    j = _skip_ows(v, j + 1, n)
    k = j
    while k < n and v[k] in _TOKEN:
        k += 1
    if v[j:k].lower() != "tag":
        raise Reject("fields")
    j = _skip_ows(v, k, n)
    if j >= n or v[j] != "=":
        raise Reject("fields")
    j = _skip_ows(v, j + 1, n)
    k = j
    while k < n and v[k] in _TOKEN:
        k += 1
    tag = v[j:k]
    tlen = len(tag)
    if tlen < 1 or tlen > 32 or k != n:
        raise Reject("fields")
    return uri, tag


def parse_to(v):
    n = len(v)
    uri, is_tel, j = parse_address(v, 0, n)
    if is_tel or j != n:
        raise Reject("fields")
    return uri


